public static class EnergyRightsFixtureData
{
    public static object Get(EnergyRightsCanvas c,string name){return typeof(EnergyRightsCanvas).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(c);}
    public static void Set(EnergyRightsCanvas c,string name,object value){typeof(EnergyRightsCanvas).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(c,value);}
    public static void Invoke(EnergyRightsCanvas c,string name){typeof(EnergyRightsCanvas).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,null);}
    public static GameObject Child(GameObject parent,string name,bool active=true){var go=new GameObject(name);go.transform.SetParent(parent.transform);go.SetActive(active);return go;}
    public static TextMeshProUGUI Label(GameObject parent,string name){var go=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer),typeof(TextMeshProUGUI));go.transform.SetParent(parent.transform);return go.GetComponent<TextMeshProUGUI>();}
    public static EnergyRightsCanvas Build(GameObject parent,string name)
    {
        var go=Child(parent,name,false);var c=go.AddComponent<EnergyRightsCanvas>();foreach(var field in typeof(EnergyRightsCanvas).GetFields(BindingFlags.Instance|BindingFlags.Public))if(field.FieldType==typeof(TextMeshProUGUI))field.SetValue(c,Label(go,field.Name));
        var jobs=Child(parent,name+"_Jobs",false).AddComponent<CanvasJobs>();jobs.goldyokbasic=Child(parent,name+"_NotEnough",false);jobs.golyokbasictxt=Label(jobs.goldyokbasic,"OriginalMessage");c.canvasJobs=jobs;return c;
    }
    public static void SetCrystal(int visible,int data){typeof(Currencys).GetProperty("Crystal").SetValue(null,visible,null);typeof(Currencys).GetField("DataCrystal",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,data);}
    public static void SetEnergy(int visible,int data){typeof(Currencys).GetProperty("Energy").SetValue(null,visible,null);typeof(Currencys).GetField("DataEnergy",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,data);}
    public static void FlushEnergy(GameObject inactiveOwner)
    {
        foreach(var name in new[]{"SaveCrystal","SaveCoin"})typeof(Currencys).GetField(name,BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);
        typeof(Currencys).GetField("SaveEnergyTimer",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,-1f);typeof(Currencys).GetMethod("Update",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(inactiveOwner.AddComponent<Currencys>(),null);
        ES3.StoreCachedFile("medupac.es3",new ES3Settings("medupac.es3",ES3.Location.File));
    }
}
public static class EnergyRightsLocalVerification
