    public static Result RunChecks()
    {
        var r=new Result();var root=new GameObject("EnergyRightsVerification");root.SetActive(false);var toggleHost=new GameObject("EnergyToggleHost");var currency=new Dictionary<FieldInfo,object>();foreach(var f in typeof(Currencys).GetFields(BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic))if(!f.IsLiteral&&!f.IsInitOnly)currency[f]=f.GetValue(null);
        var rootField=typeof(OfflineKeyStore).GetField("verificationRoot",BindingFlags.Static|BindingFlags.NonPublic);string oldRoot=(string)rootField.GetValue(null);var oldSound=SoundManager.instance;var oldParticle=BuyukParticle.Energy;int oldLanguage=GameManager.Language;var oldLang=Lang.currentLang;var oldClan=PlayerData.clanPerksDatam;var oldRandom=UnityEngine.Random.state;
        try{
