            var c=EnergyRightsFixtureData.Build(root,"Energy");EnergyRightsFixtureData.Invoke(c,"Awake");Check(r,(int)EnergyRightsFixtureData.Get(c,"adRemaining")==2&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==4,"original local default quotas2/4");Check(r,((TimeSpan)typeof(EnergyRightsCanvas).GetField("ResetInterval",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null)).TotalHours==24,"original static initializer is24 hours");
            EnergyRightsFixtureData.Invoke(c,"OnEnable");Check(r,c.claimEnergy.text==Lang.Get.GetEnergy&&c.x10Energy.text=="x10 "+Lang.Get.Energy&&c.x30Energy.text=="x30 "+Lang.Get.Energy,"original localized labels");Check(r,c.crystalCooldownText.text=="<sprite=1>100"&&c.crystalEnergyText.text=="4 "+Lang.Get.attemptsremain,"original price100 and remaining-use text");
            Currencys.CrystalFitle(500);Currencys.EnergyFitle(10);DateTime before=DateTime.UtcNow;c.CrystalHarcandi();var first=(DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime");Check(r,Currencys.Crystal==400&&Currencys.Energy==40&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==3,"first original purchase spends100 and adds30");Check(r,first>=before&&ES3.Load<DateTime>("CrystalEnergyResetTime")==first,"first use starts and saves rolling window");
            c.CrystalHarcandi();Check(r,Currencys.Crystal==300&&Currencys.Energy==70&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==2&&(DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime")==first,"second purchase preserves first-use reset timestamp");c.CrystalHarcandi();c.CrystalHarcandi();Check(r,Currencys.Crystal==100&&Currencys.Energy==130&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==0,"four original uses consume400 and add120, without natural-cap clamp");c.CrystalHarcandi();Check(r,Currencys.Crystal==100&&Currencys.Energy==130&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==0,"fifth click is blocked by exhausted quota");Check(r,c.crystalCooldownText.text.Contains("h ")&&c.crystalCooldownText.text.EndsWith("m"),"exhausted original quota displays hours/minutes");
            EnergyRightsFixtureData.FlushEnergy(root);OfflineKeyStore.ResetMemoryForVerification();EnergyRightsFixtureData.SetCrystal(0,0);EnergyRightsFixtureData.SetEnergy(0,0);Currencys.LoadStartCrystal();Currencys.LoadStartEnergy();var restarted=EnergyRightsFixtureData.Build(root,"Restarted");EnergyRightsFixtureData.Invoke(restarted,"Awake");Check(r,Currencys.Crystal==100&&Currencys.Energy==130&&(int)EnergyRightsFixtureData.Get(restarted,"crystalRemaining")==0&&(DateTime)EnergyRightsFixtureData.Get(restarted,"crystalResetTime")==first,"real local disk reread restores balances, quota and reset time");
            var oldAd=DateTime.UtcNow.AddHours(-49);var oldCrystal=DateTime.UtcNow.AddHours(-73);EnergyRightsFixtureData.Set(c,"adRemaining",0);EnergyRightsFixtureData.Set(c,"crystalRemaining",0);EnergyRightsFixtureData.Set(c,"adResetTime",oldAd);EnergyRightsFixtureData.Set(c,"crystalResetTime",oldCrystal);EnergyRightsFixtureData.Invoke(c,"RefreshRights");Check(r,(int)EnergyRightsFixtureData.Get(c,"adRemaining")==2&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==4,"elapsed rolling windows restore full quotas without stacking");Check(r,(DateTime)EnergyRightsFixtureData.Get(c,"adResetTime")==oldAd.AddHours(48)&&(DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime")==oldCrystal.AddHours(72),"multi-day catchup advances original timestamps by whole24-hour steps");Check(r,ES3.Load<int>("CrystalEnergyRemaining")==4&&ES3.Load<DateTime>("CrystalEnergyResetTime")==oldCrystal.AddHours(72),"reset quota and advanced time are saved");
