            var future=DateTime.UtcNow.AddHours(49);ES3.Save<int>("CrystalEnergyRemaining",1);ES3.Save<DateTime>("CrystalEnergyResetTime",future);ES3.Save<DateTime>("AdEnergyResetTime",future);var startRepair=DateTime.UtcNow;EnergyRightsFixtureData.Invoke(c,"Awake");Check(r,(DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime")>=startRepair&&(DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime")<DateTime.UtcNow.AddSeconds(1)&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==1,"Awake repairs dates beyond48h without granting uses");Check(r,ES3.Load<DateTime>("CrystalEnergyResetTime")== (DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime"),"future timestamp repair persists");var allowedFuture=DateTime.UtcNow.AddHours(47);ES3.Save<DateTime>("CrystalEnergyResetTime",allowedFuture);EnergyRightsFixtureData.Invoke(c,"Awake");Check(r,(DateTime)EnergyRightsFixtureData.Get(c,"crystalResetTime")==allowedFuture,"within48h future timestamp is retained as original");
