            Currencys.CrystalFitle(99);Currencys.EnergyFitle(5);EnergyRightsFixtureData.Set(c,"crystalRemaining",1);c.CrystalHarcandi();Check(r,Currencys.Crystal==99&&Currencys.Energy==5&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==1&&c.canvasJobs.goldyokbasic.activeSelf,"below100 fails with original local insufficient-crystal overlay and no charge");Check(r,c.canvasJobs.golyokbasictxt.text==Lang.Get.NotEnoughCrystals,"insufficient-balance message uses original Crystal label");
            int cap=Currencys.MaxEnergy();Currencys.CrystalFitle(100);Currencys.EnergyFitle(cap);EnergyRightsFixtureData.Set(c,"crystalRemaining",1);c.CrystalHarcandi();Check(r,Currencys.Crystal==0&&Currencys.Energy==cap+30,"original purchase remains allowed at natural energy cap");
            EnergyRightsFixtureData.SetCrystal(100,0);Currencys.EnergyFitle(5);EnergyRightsFixtureData.Set(c,"crystalRemaining",4);c.CrystalHarcandi();Check(r,Currencys.Crystal==0&&Currencys.Energy==35&&(int)EnergyRightsFixtureData.Get(c,"crystalRemaining")==3,"original visible-balance precheck and ignored Spend-return integrity window preserved");
            var toggle=EnergyRightsFixtureData.Build(toggleHost,"ActiveToggle");toggle.OpenClose();Check(r,toggle.gameObject.activeInHierarchy,"original OpenClose opens");toggle.OpenClose();Check(r,!toggle.gameObject.activeSelf,"original OpenClose closes");toggle.Close();Check(r,!toggle.gameObject.activeSelf,"Close inactive-self guard");toggle.gameObject.SetActive(true);toggle.Close();Check(r,!toggle.gameObject.activeSelf,"Close hides an active-self object");
        }catch(Exception e){r.failures.Add(e.ToString());}
